{
  "correction_rules": [
    "Reduce forecast bias when sentiment is negative (sentiment < 0) — model tends to overestimate prices.",
    "Adjust downward for recent spikes (last 5-7 days) — model often overshoots after sharp increases.",
    "Apply mean reversion correction if forecast deviates > ±10% from 30-day moving average — especially when sentiment is neutral or slightly positive.",
    "Increase downward bias if sentiment is positive (sentiment > 0) and price is trending downward — model may underreact to bullish sentiment.",
    "Apply lag correction: if true outcome is lower than forecast, reduce forecast by 5-10% for next period if sentiment remains stable or negative.",
    "Use sentiment as a momentum filter: if sentiment is positive and price is falling, add 3-5% to forecast to counteract sentiment-driven overcorrection."
  ]
}
